CREATE TRIGGER verification_desktop_owner BEFORE INSERT ON verification WHEN NEW.identifier GLOB 'calendar-desktop:*' AND json_valid(NEW.value) AND json_extract(NEW.value, '$.personId') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "user" WHERE id = json_extract(NEW.value, '$.personId')) BEGIN SELECT RAISE(ABORT, 'owner missing'); END;
CREATE TRIGGER verification_link_owner BEFORE INSERT ON verification WHEN json_valid(NEW.value) AND json_extract(NEW.value, '$.link.userId') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "user" WHERE id = json_extract(NEW.value, '$.link.userId')) BEGIN SELECT RAISE(ABORT, 'owner missing'); END;
